/* The one composer (composer.js) is used by the launcher and the side chat. Pages that load only tuck-art.js get it
   loaded from beside this file, so every page shares the same box without wiring it twice. */
window.tuckComposerReady=new Promise(res=>{const me=document.currentScript,base=me&&me.src?me.src.replace(/[^/]*$/,''):'';
  const go=()=>{if(window.Composer)return res();if(document.querySelector('script[src$="composer.js"]')){addEventListener('load',res);return}
    const s=document.createElement('script');s.src=base+'composer.js';s.onload=res;s.onerror=res;document.head.appendChild(s)};
  if(window.Composer)res();else if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',go);else go()});

/* Long file names keep their start and their end: "Screenshot 2026-10-28 at 09.30.png" -> "Screenshot…09.30.png". */
window.tuckMid=function(name,max=22){name=String(name);if(name.length<=max)return name;
  const dot=name.lastIndexOf('.'),ext=dot>0&&name.length-dot<=6?name.slice(dot):'';const tail=Math.min(ext.length+5,Math.floor(max/2));
  return name.slice(0,Math.max(1,max-tail-1)).trimEnd()+'…'+name.slice(-tail).trimStart()};

/* Tuck on the app pages, the same physics as onboarding: pick him up and throw him anywhere. He flies with gravity,
   bounces off the window and the floor, skids with little dust puffs, shakes it off after a hard landing, walks home
   on his walk frames and hops back into his corner. A soft ground shadow (the dot) follows him the whole time.
   Reduced motion: he fades out where you dropped him and fades back in at home.

   Idle wander (findings item 22), opt-in with {wander:true} or {wander:{every:[ms,ms], idle:ms, max:px, when:()=>bool}}:
   every 20-40 s, once the person has been still for 10 s, Tuck strolls a little along the bottom edge on his walk frames,
   looks around, and walks back. He never covers content: before each stroll he probes the floor strip beside him with
   elementFromPoint and only walks as far as the strip shows the same empty backdrop he stands on (8 px steps), capped
   at 96 px. If the strip is busy, or he stands on content already (a canvas, a list row), he stays put. No wander with
   Reduce Motion, while the page is hidden, while the launcher, a notice or the side chat is open, or mid-drag. */
