    const s=g.samples,a=s[0],b=s[s.length-1];let vx=0,vy=0;const dt0=(b.t-a.t)/1000;
    if(dt0>.008){vx=(b.x-a.x)/dt0;vy=(b.y-a.y)/dt0}if(e.timeStamp-b.t>70)vx=vy=0;const sp=Math.hypot(vx,vy);if(sp>MAXV){vx*=MAXV/sp;vy*=MAXV/sp}
