  function get(){const raw=rd(K,{})||{},q=Object.assign({},DEF,raw);
    if(!Array.isArray(raw.cards)&&window.Plan&&Plan.needs){const v=Plan.view(),last={};rd('tuckAnswers',[]).forEach(x=>last[x.id]=x.a);const answered=new Set(Object.keys(last).filter(id=>last[id]==='yes'||last[id]==='no'));
      q.cards=Plan.needs().filter(x=>!x.done&&!answered.has(x.id)).map(x=>{const f=x.file&&v.file(x.file);
        return {id:x.id,q:x.q,yes:x.yes||'Yes',sure:x.sure||null,n:x.n||1,files:f?[f.name]:x.node&&v.node(x.node)?v.files(x.node,true).slice(0,3).map(y=>y.name):[]}});
      if(typeof raw.left!=='number')q.left=q.cards.length}
    if(!Array.isArray(raw.tidy)&&Array.isArray(window.TIDY_GROUPS)){const done=new Set(rd('tuckTidyDone',[]));
      q.tidy=TIDY_GROUPS.filter(g=>!done.has(g.id)).map(g=>({id:g.id,leg:g.leg,ic:g.ic,n:g.items.length,mb:Math.round(g.items.reduce((a,x)=>a+x[1],0))}));
      if(typeof raw.tidyMB!=='number')q.tidyMB=q.tidy.reduce((a,g)=>a+g.mb,0)}
    else if(typeof raw.tidyMB!=='number'&&typeof window.TIDY_MB==='number')q.tidyMB=Math.round(TIDY_MB);
    /* tuckTidyDone is the one Clean Up state (rule 13): a group listed there is gone on every page, whatever an older tuckQueue says */
    if(Array.isArray(raw.tidy)){const done=new Set(rd('tuckTidyDone',[]));if(q.tidy.some(g=>done.has(g.id))){q.tidy=q.tidy.filter(g=>!done.has(g.id));q.tidyMB=q.tidy.reduce((a,g)=>a+g.mb,0)}}
    return q}
  const markDone=(ids,on)=>{const done=new Set(rd('tuckTidyDone',[]));ids.forEach(i=>on?done.add(i):done.delete(i));wr('tuckTidyDone',[...done])};
  function answer(id,a){const q=get(),i=q.cards.findIndex(c=>c.id===id);if(i<0)return q;const [c]=q.cards.splice(i,1);
    if(a==='skip')q.cards.push(c);else q.left=Math.max(0,q.left-1);wr(K,q);
    const as=rd('tuckAnswers',[]);as.push({id,a,t:Date.now()});wr('tuckAnswers',as);fire();return q}
  function trash(ids){const q=get(),done=new Set(rd('tuckTidyDone',[]));ids.forEach(i=>done.add(i));wr('tuckTidyDone',[...done]);
    const gone=q.tidy.filter(g=>ids.includes(g.id));q.tidy=q.tidy.filter(g=>!ids.includes(g.id));q.tidyMB=Math.max(0,Math.round(q.tidyMB-gone.reduce((a,g)=>a+g.mb,0)));wr(K,q);fire();return gone}
